import type { Item, Kind, Ledger, Profile, Scope } from '../types'

export const PLUGIN = 'loadout'
export const DEFAULT_PROFILE_NAME = 'default'
export const VANILLA_PROFILE_NAME = 'vanilla'
export const DEFAULT_PROFILE: Profile = {
  name: DEFAULT_PROFILE_NAME,
  base: 'on',
  overrides: {},
}
export const VANILLA_PROFILE: Profile = {
  name: VANILLA_PROFILE_NAME,
  base: 'off',
  overrides: {},
}
export const INITIAL_PROFILES: readonly Profile[] = [DEFAULT_PROFILE, VANILLA_PROFILE]

const LEGACY_VANILLA_PROFILE_NAME = 'pristine'

const PROFILE_NAME = /^[A-Za-z0-9_-]{1,40}$/
const KINDS_KEPT_BY_BASE: readonly Kind[] = ['permission', 'setting']

export const KIND_LABELS: Readonly<Record<Kind, string>> = {
  instruction: 'CLAUDE.md',
  rule: 'Rules',
  memory: 'Memories',
  skill: 'Skills & commands',
  agent: 'Agents',
  mcp: 'MCP servers',
  'hook-event': 'Hook events',
  hook: 'Hooks',
  plugin: 'Plugins',
  permission: 'Permissions',
  setting: 'Settings',
}

export const KINDS = Object.keys(KIND_LABELS) as Kind[]

export const SCOPES: readonly Scope[] = [
  'policy',
  'flag',
  'local',
  'project',
  'user',
  'plugin',
  'account',
  'memory',
  'mixed',
]

export const isValidProfileName = (name: string) => PROFILE_NAME.test(name)

export const nameProblem = (profiles: readonly Profile[], name: string) => {
  if (name === '') return 'A profile name is required.'
  if (!isValidProfileName(name))
    return 'A profile name is 1-40 letters, digits, "-" or "_".'
  if (profiles.some(profile => profile.name === name))
    return `Profile "${name}" already exists.`

  return undefined
}

export const isFixedProfile = (name: string) => name === VANILLA_PROFILE_NAME

export const fallbackProfile = (profiles: readonly Profile[]) =>
  profiles.find(profile => !isFixedProfile(profile.name)) ?? VANILLA_PROFILE

export const findProfile = (profiles: readonly Profile[], name: string) =>
  profiles.find(profile => profile.name === name) ?? fallbackProfile(profiles)

export const isEnabled = (profile: Profile, item: Item) => {
  if (item.isLocked) return true
  const override = profile.overrides[item.id]
  if (override !== undefined) return override
  if (KINDS_KEPT_BY_BASE.includes(item.kind)) return true

  return profile.base === 'on'
}

export const EMPTY_LEDGER: Ledger = { stash: {}, raised: [] }

export const desiredState = (profile: Profile, item: Item, ledger: Ledger) => {
  if (item.entry === undefined) return isEnabled(profile, item)
  if (item.isLocked) return item.isOn
  const override = profile.overrides[item.id]
  if (override !== undefined) return override
  const wasOnBeforeLoadout =
    !ledger.raised.includes(item.id) &&
    (item.isOn || ledger.stash[item.id] !== undefined)
  if (KINDS_KEPT_BY_BASE.includes(item.kind)) return wasOnBeforeLoadout

  return profile.base === 'on' && wasOnBeforeLoadout
}

export const isShownOn = (profile: Profile, item: Item) =>
  item.entry === undefined ? isEnabled(profile, item) : item.isOn

export const isOnIn = (
  profile: Profile,
  item: Item,
  ledger: Ledger,
  isApplied: boolean,
) => (isApplied ? isShownOn(profile, item) : desiredState(profile, item, ledger))

export const withOverride = (
  profile: Profile,
  id: string,
  isOn: boolean,
): Profile => ({
  ...profile,
  overrides: { ...profile.overrides, [id]: isOn },
})

export const upsertProfile = (
  profiles: readonly Profile[],
  profile: Profile,
): Profile[] =>
  profiles.some(one => one.name === profile.name)
    ? profiles.map(one => (one.name === profile.name ? profile : one))
    : [...profiles, profile]

export const removeProfile = (
  profiles: readonly Profile[],
  name: string,
): Profile[] => profiles.filter(profile => profile.name !== name)

export const renameProfile = (
  profiles: readonly Profile[],
  from: string,
  to: string,
): Profile[] =>
  profiles.map(profile => (profile.name === from ? { ...profile, name: to } : profile))

const currentNameOf = (name: string) =>
  name === LEGACY_VANILLA_PROFILE_NAME ? VANILLA_PROFILE_NAME : name

export const withoutLegacyNames = (profiles: readonly Profile[]): Profile[] =>
  profiles.some(profile => profile.name === VANILLA_PROFILE_NAME)
    ? [...profiles]
    : renameProfile(profiles, LEGACY_VANILLA_PROFILE_NAME, VANILLA_PROFILE_NAME)

export const withVanilla = (profiles: readonly Profile[]): Profile[] =>
  profiles.some(profile => isFixedProfile(profile.name))
    ? profiles.map(profile => (isFixedProfile(profile.name) ? VANILLA_PROFILE : profile))
    : [...profiles, VANILLA_PROFILE]

export const restoredProfiles = (
  stored: readonly Profile[] | undefined,
  wanted: unknown,
) => {
  const profiles = withVanilla(withoutLegacyNames(stored ?? INITIAL_PROFILES))
  const isNamed = (name: unknown) => profiles.some(profile => profile.name === name)
  const carried = isNamed(wanted) ? String(wanted) : currentNameOf(String(wanted))

  return {
    profiles,
    active: isNamed(carried) ? carried : fallbackProfile(profiles).name,
  }
}

files.hooks/settingsEdit.ts:
import type {
  Item,
  Json,
  Scope,
  SettingsEntry,
  WritableSource,
} from '../types'

export type SettingsObject = { [key: string]: Json }
export type SettingsSourceName = WritableSource | 'policy' | 'flag'

const PERMISSION_LISTS = ['allow', 'deny', 'ask'] as const
const SPECIAL_KEYS = ['enabledPlugins', 'permissions', 'hooks']
const NAME_LIMIT = 70
const WRITABLE: readonly string[] = ['user', 'project', 'local']

export const isObject = (value: unknown): value is SettingsObject =>
  typeof value === 'object' && value !== null && !Array.isArray(value)

const CONTROL_CHARACTERS = /[\u0000-\u001f\u007f]/g

const clip = (raw: string) => {
  const text = raw.replace(CONTROL_CHARACTERS, ' ')

  return text.length > NAME_LIMIT ? `${text.slice(0, NAME_LIMIT - 1)}…` : text
}

const describeValue = (key: string, value: Json) => {
  if (typeof value === 'boolean' || typeof value === 'number' || value === null)
    return `${key} = ${String(value)}`
  if (typeof value === 'string') return `${key} (text)`
  if (Array.isArray(value)) return `${key} (list of ${value.length})`

  return `${key} {${Object.keys(value).join(', ')}}`
}

const isSame = (left: Json, right: Json) =>
  JSON.stringify(left) === JSON.stringify(right)

const getAt = (root: Json, path: readonly string[]): Json | undefined =>
  path.reduce<Json | undefined>(
    (node, key) => (isObject(node) ? node[key] : undefined),
    root,
  )

const setAt = (
  root: SettingsObject,
  path: readonly string[],
  value: Json | undefined,
): SettingsObject => {
  const [head, ...rest] = path
  if (head === undefined) return root
  if (rest.length > 0) {
    const child = root[head]

    return { ...root, [head]: setAt(isObject(child) ? child : {}, rest, value) }
  }
  if (value !== undefined) return { ...root, [head]: value }
  const { [head]: removed, ...kept } = root

  return kept
}

export const applyEntry = (
  settings: SettingsObject,
  entry: SettingsEntry,
  isOn: boolean,
): SettingsObject => {
  if (entry.mode === 'flag')
    return setAt(
      settings,
      entry.path,
      isOn && entry.value !== false ? entry.value : isOn,
    )
  if (entry.mode === 'key')
    return setAt(settings, entry.path, isOn ? entry.value : undefined)
  const current = getAt(settings, entry.path)
  const list = Array.isArray(current) ? current : []
  const others = list.filter(one => !isSame(one, entry.value))

  return setAt(settings, entry.path, isOn ? [...others, entry.value] : others)
}

const hookName = (event: string, hook: Json) => {
  if (!isObject(hook)) return `${event}: ${clip(JSON.stringify(hook))}`
  const matcher = typeof hook.matcher === 'string' ? hook.matcher : '*'
  const first = Array.isArray(hook.hooks) ? hook.hooks[0] : undefined
  const command =
    isObject(first) && typeof first.command === 'string'
      ? first.command
      : JSON.stringify(first ?? null)

  return clip(`${event} [${matcher}] ${command}`)
}

type Draft = Pick<Item, 'kind' | 'name' | 'isOn' | 'event'> & {
  mode: SettingsEntry['mode']
  path: string[]
  value: Json
}

const pluginDrafts = (settings: SettingsObject): Draft[] =>
  Object.entries(isObject(settings.enabledPlugins) ? settings.enabledPlugins : {})
    .map(([name, value]) => ({
      kind: 'plugin' as const,
      name,
      isOn: value !== false,
      mode: 'flag' as const,
      path: ['enabledPlugins', name],
      value,
    }))

const permissionDrafts = (settings: SettingsObject): Draft[] => {
  const permissions = isObject(settings.permissions) ? settings.permissions : {}
  const rules = PERMISSION_LISTS.flatMap(list => {
    const values = permissions[list]

    return (Array.isArray(values) ? values : []).map(rule => ({
      kind: 'permission' as const,
      name: clip(`${list}: ${typeof rule === 'string' ? rule : JSON.stringify(rule)}`),
      isOn: true,
      mode: 'element' as const,
      path: ['permissions', list],
      value: rule,
    }))
  })
  const others = Object.entries(permissions)
    .filter(([key]) => !PERMISSION_LISTS.some(list => list === key))
    .map(([key, value]) => ({
      kind: 'permission' as const,
      name: clip(`${key} = ${JSON.stringify(value)}`),
      isOn: true,
      mode: 'key' as const,
      path: ['permissions', key],
      value,
    }))

  return [...rules, ...others]
}

const hookDrafts = (settings: SettingsObject): Draft[] =>
  Object.entries(isObject(settings.hooks) ? settings.hooks : {}).flatMap(
    ([event, hooks]) =>
      (Array.isArray(hooks) ? hooks : []).map(hook => ({
        kind: 'hook' as const,
        event,
        name: hookName(event, hook),
        isOn: true,
        mode: 'element' as const,
        path: ['hooks', event],
        value: hook,
      })),
  )

const settingDrafts = (settings: SettingsObject): Draft[] =>
  Object.entries(settings)
    .filter(([key]) => !SPECIAL_KEYS.includes(key))
    .map(([key, value]) => ({
      kind: 'setting' as const,
      name: clip(describeValue(key, value)),
      isOn: true,
      mode: 'key' as const,
      path: [key],
      value,
    }))

export const entryIdOf = (
  kind: string,
  origin: string,
  entry: Pick<SettingsEntry, 'mode' | 'path' | 'value'>,
) =>
  [
    kind,
    origin,
    entry.path.join('.'),
    entry.mode === 'element' ? JSON.stringify(entry.value) : '',
  ].join(':')

const uniqueById = (items: readonly Item[]) =>
  items.filter((item, index) => items.findIndex(one => one.id === item.id) === index)

export const entriesOf = (
  settings: SettingsObject,
  source: SettingsSourceName,
  origin: string,
): Item[] =>
  uniqueById(
    [
      ...pluginDrafts(settings),
      ...permissionDrafts(settings),
      ...hookDrafts(settings),
      ...settingDrafts(settings),
    ].map(({ mode, path, value, ...shown }) => {
      const base = {
        ...shown,
        id: entryIdOf(shown.kind, origin, { mode, path, value }),
        scope: source as Scope,
        origin,
      }

      return WRITABLE.includes(source)
        ? {
            ...base,
            isLocked: false,
            entry: { mode, source: source as WritableSource, path, value },
          }
        : { ...base, isLocked: true }
    }),
  )

const ROOT_KEY_OF_KIND: Readonly<Record<string, string>> = {
  plugin: 'enabledPlugins',
  permission: 'permissions',
  hook: 'hooks',
}
const MODES: readonly string[] = ['flag', 'key', 'element']

export const isSoundStashedItem = (value: unknown): value is Item => {
  if (!isObject(value) || !isObject(value.entry)) return false
  const { id, kind, name, origin, entry } = value
  const { mode, source, path } = entry
  if (typeof id !== 'string' || typeof kind !== 'string') return false
  if (typeof name !== 'string' || typeof origin !== 'string') return false
  if (typeof mode !== 'string' || !MODES.includes(mode)) return false
  if (typeof source !== 'string' || !WRITABLE.includes(source)) return false
  if (!Array.isArray(path) || path.length === 0) return false
  if (!path.every((key): key is string => typeof key === 'string')) return false
  if (entry.value === undefined) return false
  const rootKey = ROOT_KEY_OF_KIND[kind]
  const isRootRight =
    kind === 'setting'
      ? !SPECIAL_KEYS.includes(path[0] ?? '')
      : rootKey !== undefined && path[0] === rootKey

  return (
    isRootRight &&
    id === entryIdOf(kind, origin, { mode: mode as SettingsEntry['mode'], path, value: entry.value })
  )
}

export const hookEventOf = (item: Item) =>
  item.kind === 'hook' ? item.event : undefined

files.hooks/view.tsx:
import type { Elements } from 'claude-code'

import type { Item, Kind, Picker, Profile, ProfileAction, Scope, View } from '../types'
import { KINDS, KIND_LABELS, SCOPES, isFixedProfile } from './model'
import { projectLabel } from './project'

export type PaneElements = Pick<
  Elements['terminal'],
  'Box' | 'Text' | 'Button' | 'Input' | 'Link'
>

export type PaneActions = {
  onToggle: (id: string) => void
  onAction: (name: string, action: ProfileAction) => void
  onCreate: (name: string) => void
  onRename: (name: string) => void
  onRefresh: () => void
  onProject: (path: string) => void
  onView: (patch: Partial<View>) => void
}

export type PaneModel = {
  items: readonly Item[]
  root: string
  projects: readonly string[]
  profiles: readonly Profile[]
  profile: Profile
  applied: string
  isOn: (item: Item) => boolean
  view: View
  columns: number
  rows: number
  isDocked: boolean
}

type SectionLine = { kind: Kind; isOpen: boolean; count: number; offCount: number }
type ItemLine = { item: Item; isInSection: boolean }
type Line = SectionLine | ItemLine
type PickerOption = { value: string; label: string }
type OpenPicker = Exclude<Picker, 'none'>

const CHROME_ROWS = 15
const FRAME_COLUMNS = 4
const FRAME = { borderStyle: 'round', borderDimColor: true, paddingX: 1 } as const
const MIN_LIST_ROWS = 3
const INDENT_COLUMNS = 2
const CHECKBOX_COLUMNS = 1
const SCOPE_COLUMNS = 9
const NAME_SHARE = 0.5
const ALL = 'all'
const CHECKED = '☑'
const UNCHECKED = '☐'
const OPEN_MARK = '▾'
const CLOSED_MARK = '▸'
const KINDS_WITHOUT_SECTION: readonly Kind[] = ['instruction']
const PROFILE_KEY_PREFIX = 'profile:'
const MENU_KEY_PREFIX = 'menu:'
const ACTION_KEY_PREFIX = 'action:'
const PICKER_KEY_PREFIX = 'picker:'
const PICK_KEY_PREFIX = 'pick:'
const PICKER_LABELS: Readonly<Record<OpenPicker, string>> = {
  project: 'Project',
  scope: 'Scope',
}
const APPLIED_COLOR = 'suggestion'
const MENU_BORDER_ROWS = 2
const ORIGIN_NOTE = / (\(@import from .*\)|or commands)$/
const FILE_SCHEME = 'file://'
const PROFILE_ACTIONS: readonly ProfileAction[] = ['apply', 'duplicate', 'rename', 'delete']
const FIXED_PROFILE_ACTIONS: readonly ProfileAction[] = ['apply', 'duplicate']
const NAME_FIELDS = {
  new: { key: 'new-profile-name', verb: 'Duplicate', submitLabel: 'create' },
  rename: { key: 'rename-profile-name', verb: 'Rename', submitLabel: 'rename' },
} as const

const clipEnd = (text: string, width: number) =>
  text.length > width ? `${text.slice(0, Math.max(1, width - 1))}…` : text

const clipStart = (text: string, width: number) =>
  text.length > width ? `…${text.slice(text.length - Math.max(1, width - 1))}` : text

const actionsOf = (name: string) =>
  isFixedProfile(name) ? FIXED_PROFILE_ACTIONS : PROFILE_ACTIONS

const pageSize = (rows: number, menuRows = 0) =>
  Math.max(MIN_LIST_ROWS, rows - CHROME_ROWS - menuRows)

const withToggledSection = (open: readonly Kind[], kind: Kind): Kind[] =>
  open.includes(kind) ? open.filter(one => one !== kind) : [...open, kind]

const linesOf = (
  items: readonly Item[],
  isOn: (item: Item) => boolean,
  view: View,
): Line[] => {
  const visible = items.filter(item => view.scope === ALL || item.scope === view.scope)

  return KINDS.flatMap((kind): Line[] => {
    const ofKind = visible.filter(item => item.kind === kind)
    if (ofKind.length === 0) return []
    if (KINDS_WITHOUT_SECTION.includes(kind))
      return ofKind.map(item => ({ item, isInSection: false }))
    const isOpen = view.open.includes(kind)

    return [
      {
        kind,
        isOpen,
        count: ofKind.length,
        offCount: ofKind.filter(item => !isOn(item)).length,
      },
      ...(isOpen ? ofKind.map(item => ({ item, isInSection: true })) : []),
    ]
  })
}

export const menuKeyOf = (name: string) => `${MENU_KEY_PREFIX}${name}`

const fileLinkOf = (origin: string) =>
  origin.startsWith('/')
    ? `${FILE_SCHEME}${origin.replace(ORIGIN_NOTE, '').split('/').map(encodeURIComponent).join('/')}`
    : undefined

export const drawBand = (
  { Box, Button }: Pick<PaneElements, 'Box' | 'Button'>,
  profileName: string,
  onOpen: () => void,
) => (
  <Box>
    <Button
      key="open-pane"
      plain
      dimColor
      label={`↗ loadout · ${profileName}`}
      onPress={onOpen}
    />
  </Box>
)

export const drawPane = (
  { Box, Text, Button, Input, Link }: PaneElements,
  {
    items,
    root,
    projects,
    profiles,
    profile,
    applied,
    isOn,
    view,
    columns,
    rows,
    isDocked,
  }: PaneModel,
  actions: PaneActions,
) => {
  const isMenuOpen = view.edit === 'menu' && view.target === profile.name
  const menuActions = isMenuOpen ? actionsOf(profile.name) : []
  const lines = linesOf(items, isOn, view)
  const room = Math.max(20, columns - FRAME_COLUMNS - INDENT_COLUMNS - CHECKBOX_COLUMNS - SCOPE_COLUMNS - 2)
  const nameWidth = Math.floor(room * NAME_SHARE)
  const isRenaming =
    view.edit === 'rename' &&
    !isFixedProfile(view.target) &&
    profiles.some(one => one.name === view.target)
  const scopeOptions: PickerOption[] = [
    { value: ALL, label: 'All' },
    ...SCOPES.filter(scope => items.some(item => item.scope === scope)).map(scope => ({
      value: scope,
      label: scope,
    })),
  ]
  const shownProject = view.project === '' ? root : view.project
  const projectOptions: PickerOption[] = [
    ...new Set([root, ...projects, shownProject]),
  ].map(path => ({ value: path, label: projectLabel(path, root) }))
  const pickers = {
    project: {
      options: projectOptions,
      picked: shownProject,
      onPick: actions.onProject,
    },
    scope: {
      options: scopeOptions,
      picked: view.scope,
      onPick: (value: string) =>
        actions.onView({ scope: value as Scope | 'all', page: 0, picker: 'none' }),
    },
  }
  const openRows = [
    ...(isMenuOpen ? [menuActions.length] : []),
    ...(view.picker === 'none' ? [] : [pickers[view.picker].options.length]),
  ].reduce((total, count) => total + count + MENU_BORDER_ROWS, 0)
  const size = pageSize(rows, openRows)
  const pages = Math.max(1, Math.ceil(lines.length / size))
  const page = Math.min(view.page, pages - 1)
  const drawNameField = (edit: keyof typeof NAME_FIELDS, onSubmit: (name: string) => void) => (
    <Box flexDirection="row" gap={1}>
      <Input
        key={NAME_FIELDS[edit].key}
        label={`${NAME_FIELDS[edit].verb} "${view.target}"`}
        placeholder="name"
        {...(edit === 'rename' ? { value: view.target } : {})}
        submitLabel={NAME_FIELDS[edit].submitLabel}
        autoFocus
        onSubmit={onSubmit}
      />
      <Button
        key="cancel-edit"
        plain
        dimColor
        label="Cancel"
        onPress={() => actions.onView({ edit: 'none' })}
      />
    </Box>
  )

  const drawPicker = (picker: OpenPicker) => {
    const { options, picked, onPick } = pickers[picker]
    const isOpen = view.picker === picker
    const pickedLabel = options.find(option => option.value === picked)?.label ?? picked

    return (
      <Box flexDirection="column">
        <Box flexDirection="row" gap={1}>
          <Text dimColor>{PICKER_LABELS[picker]}</Text>
          <Button
            key={`${PICKER_KEY_PREFIX}${picker}`}
            plain
            label={`${pickedLabel} ${isOpen ? OPEN_MARK : CLOSED_MARK}`}
            onPress={() => actions.onView({ picker: isOpen ? 'none' : picker })}
          />
        </Box>
        {isOpen && (
          <Box key="picker-menu" flexDirection="column" {...FRAME}>
            {options.map(option => (
              <Button
                key={`${PICK_KEY_PREFIX}${picker}:${option.value}`}
                plain
                dimColor={option.value !== picked}
                label={option.label}
                onPress={() => onPick(option.value)}
              />
            ))}
          </Box>
        )}
      </Box>
    )
  }

  const drawSection = (line: SectionLine) => (
    <Box flexDirection="row" gap={1}>
      <Button
        key={`section:${line.kind}`}
        plain
        label={`${line.isOpen ? OPEN_MARK : CLOSED_MARK} ${KIND_LABELS[line.kind]}`}
        onPress={() =>
          actions.onView({ open: withToggledSection(view.open, line.kind), page })
        }
      />
      <Text dimColor>{line.count}</Text>
      {line.offCount > 0 && <Text color="warning">{line.offCount} off</Text>}
    </Box>
  )

  const drawItem = ({ item, isInSection }: ItemLine) => {
    const isItemOn = isOn(item)
    const origin = clipStart(
      item.isLocked ? `locked · ${item.origin}` : item.origin,
      room - nameWidth,
    )
    const fileLink = fileLinkOf(item.origin)

    return (
      <Box flexDirection="row" gap={1} paddingLeft={isInSection ? INDENT_COLUMNS : 0}>
        {item.isLocked ? (
          <Text dimColor>{CHECKED}</Text>
        ) : (
          <Button
            key={`toggle:${item.id}`}
            plain
            label={isItemOn ? CHECKED : UNCHECKED}
            onPress={() => actions.onToggle(item.id)}
          />
        )}
        <Text dimColor={!isItemOn}>{clipEnd(item.name, nameWidth).padEnd(nameWidth)}</Text>
        <Text color="suggestion" dimColor={!isItemOn}>
          {item.scope.padEnd(SCOPE_COLUMNS - 2)}
        </Text>
        <Text dimColor>
          {fileLink === undefined ? origin : <Link href={fileLink} label={origin} />}
        </Text>
      </Box>
    )
  }

  const drawProfile = (one: Profile) => {
    const isApplied = one.name === applied
    const isShown = one.name === profile.name

    return (
      <Box flexDirection="column">
        <Box flexDirection="row" gap={1}>
          <Box flexDirection="row">
            {isApplied && <Text color={APPLIED_COLOR}>[</Text>}
            {isApplied && isShown ? (
              <Text color={APPLIED_COLOR}>{one.name}</Text>
            ) : (
              <Button
                key={`${PROFILE_KEY_PREFIX}${one.name}`}
                plain
                dimColor={!isShown}
                label={one.name}
                onPress={() =>
                  actions.onView({
                    viewed: one.name,
                    ...(view.edit === 'menu' ? { edit: 'none' as const } : {}),
                  })
                }
              />
            )}
            {isApplied && <Text color={APPLIED_COLOR}>]</Text>}
          </Box>
          {isShown && (
            <Button
              key={menuKeyOf(one.name)}
              plain
              label={isMenuOpen ? OPEN_MARK : CLOSED_MARK}
              onPress={() =>
                actions.onView(isMenuOpen ? { edit: 'none' } : { edit: 'menu', target: one.name })
              }
            />
          )}
        </Box>
        {isShown && isMenuOpen && (
          <Box key="profile-menu" flexDirection="column" {...FRAME}>
            {menuActions.map(action => (
              <Button
                key={`${ACTION_KEY_PREFIX}${action}`}
                plain
                label={action}
                onPress={() => actions.onAction(one.name, action)}
              />
            ))}
          </Box>
        )}
      </Box>
    )
  }

  return (
    <Box flexDirection="column" {...(isDocked ? { minHeight: rows } : {})}>
      <Box flexDirection="row" justifyContent="space-between">
        <Box flexDirection="row" gap={1}>
          <Text bold color="claude">
            Loadout
          </Text>
          <Text dimColor>{profile.name}</Text>
        </Box>
        <Box key="refresh-frame" {...FRAME}>
          <Button key="refresh" plain dimColor label="Refresh" onPress={actions.onRefresh} />
        </Box>
      </Box>
      <Box flexDirection="row" gap={2} marginBottom={1}>
        {drawPicker('project')}
        {drawPicker('scope')}
      </Box>
      <Box flexDirection="column" {...FRAME}>
        {lines.length === 0 && <Text dimColor>Nothing here in this scope.</Text>}
        {lines
          .slice(page * size, (page + 1) * size)
          .map(line => ('kind' in line ? drawSection(line) : drawItem(line)))}
      </Box>
      {pages > 1 && (
        <Box flexDirection="row" gap={1} justifyContent="center">
          <Button
            key="prev"
            plain
            label="Prev"
            hotkey="p"
            onPress={() => actions.onView({ page: Math.max(0, page - 1) })}
          />
          <Text dimColor>
            page {page + 1}/{pages}
          </Text>
          <Button
            key="next"
            plain
            label="Next"
            hotkey="n"
            onPress={() => actions.onView({ page: Math.min(pages - 1, page + 1) })}
          />
        </Box>
      )}
      <Box flexGrow={1} />
      {view.notice !== '' && <Text dimColor>{clipEnd(view.notice, columns * 2)}</Text>}
      {view.edit === 'new' && drawNameField('new', actions.onCreate)}
      {isRenaming && drawNameField('rename', actions.onRename)}
      <Box key="profile-tabs" flexDirection="row" gap={2} flexWrap="wrap" {...FRAME}>
        {profiles.map(drawProfile)}
        <Button
          key="new-profile"
          plain
          label="+"
          onPress={() => actions.onView({ edit: 'new', target: profile.name })}
        />
      </Box>
    </Box>
  )
}

